function floorList(){let a=[];for(let n=FB;n>=1;n--)a.push({key:'B'+n,label:'지하 '+n+'층'});for(let n=1;n<=FA;n++)a.push({key:n+'F',label:'지상 '+n+'층'});return a}const floors=floorList();
floors.forEach(f=>{if(!PLAN.floors[f.key])PLAN.floors[f.key]={label:f.label,use:'',occupants:0,vulnerable:'',primary_route:'',alternate_route:'',guide:'',checker:''}});
const routeChoices=f=>f.key[0]==='B'?['가까운 계단 → 1층 외부','반대편 계단 → 1층 외부','경사로 → 외부']:f.key==='1F'?['가까운 출입구 → 외부','정문 → 외부','후문 → 외부']:['동쪽 계단 → 1층 외부','서쪽 계단 → 1층 외부','가까운 피난계단 → 1층 외부'];
const steps=[{key:'alarm_method',type:'choice',q:'화재를 발견했을 때 건물 전체에 어떻게 알리나요?',options:['자동화재탐지설비·비상방송','발신기 작동 후 육성 전파','비상방송 후 층별 연락','직접 입력'],ph:'경보와 상황 전파 방법'},{key:'reporter',type:'choice',q:'119 신고와 소방대 안내는 누가 담당하나요?',options:['소방안전관리자','관리실·방재실 직원','최초 발견자','직접 입력'],ph:'담당자 이름 또는 직책'},{key:'controller',type:'choice',q:'전체 피난을 지휘할 사람은 누구인가요?',options:[...(MANAGER?[MANAGER+' 소방안전관리자']:[]),'관리실 책임자','자위소방대장','직접 입력'],ph:'담당자 이름 또는 직책',def:MANAGER},...floors.flatMap(f=>[{floor:f,key:'use',type:'choice',q:f.label+'의 용도를 확인해주세요. 이 건물은 전체적으로 '+(BUILDING.use||'용도 미설정')+'입니다.',options:['사무실','상가·판매장','주차장','창고·기계실','숙박·주거','공용공간','직접 입력'],ph:'이 층의 실제 용도'},{floor:f,key:'occupants',type:'number',q:f.label+'의 최대 재실 인원은 몇 명인가요?',options:['10','30','50','100'],ph:'직접 숫자 입력'},{floor:f,key:'vulnerable',type:'choice',q:f.label+'에 피난을 도와야 할 사람이 있나요?',options:['없음','고령자 있음','장애인 있음','환자·임산부 있음','어린이 있음','직접 입력'],hint:'해당하면 선택 후 인원이나 지원 담당자를 덧붙여 수정할 수 있습니다.',ph:'예: 휠체어 이용자 1명 · 김OO 지원'},{floor:f,key:'routes',type:'pair',q:f.label+'은 '+(f.key==='1F'?'외부 출입구로 바로 대피':'계단을 이용해 1층 외부로 대피')+'하도록 실제 경로를 확인해주세요.',labels:['주 대피경로','대체 대피경로'],ph:['주 경로 직접 입력','대체 경로 직접 입력'],pairOptions:[routeChoices(f),routeChoices(f)]},{floor:f,key:'staff',type:'pair',q:f.label+'의 피난유도와 마지막 잔류자 확인 담당자를 정해주세요.',labels:['피난유도 담당','최종 확인 담당'],ph:['이름 또는 직책','이름 또는 직책'],pairOptions:[['층별 책임자','자위소방대 피난유도반','관리실 직원'],['층별 책임자','자위소방대 피난유도반','관리실 직원']]}]),{key:'assembly_confirmed',type:'choice',q:'모든 층의 대피가 끝나면 어디에 모일까요?',options:[...(ASSEMBLY?[ASSEMBLY]:[]),'건물 앞 공터','주차장','인근 공원·광장','직접 입력'],ph:'최종 집결지',def:ASSEMBLY},{key:'headcount_method',type:'choice',q:'집결지에서 인원을 어떻게 확인하고 보고할까요?',options:['층별 담당자가 명부 확인 후 총괄 보고','부서별 책임자가 인원 확인','현장 인원 호명 후 확인','직접 입력'],ph:'인원 확인 및 보고 방법'},{key:'special_notes',type:'choice',q:'피난 시 특별히 주의할 사항이 있나요?',options:['특이사항 없음','공사·폐쇄 구간 있음','피난약자 우선 지원 필요','야간·무인시간 별도 대응 필요','직접 입력'],hint:'선택한 뒤 구체적인 내용을 직접 수정할 수 있습니다.',ph:'현장 특이사항'}];
let activeGroups=[];
function restoreGroups(){activeGroups=(PLAN.floor_groups||[]).map(g=>({name:g.name||'같은 피난구간',floors:(g.floors||[]).map(k=>floors.find(f=>f.key===k)).filter(Boolean)})).filter(g=>g.floors.length);}
function groupLabel(fs){if(fs.length===1)return fs[0].label;return fs[0].label+' ~ '+fs[fs.length-1].label+' ('+fs.length+'개 층)'}
function setRecommendedGroups(){document.querySelectorAll('.floor-pick select').forEach(s=>{let k=s.dataset.floor;s.value=k[0]==='B'?'B':k==='1F'?'ONE':'UP'});}
function setIndividualGroups(){document.querySelectorAll('.floor-pick select').forEach(s=>s.value='I_'+s.dataset.floor);}
function openFloorGrouping(){
 const groupGrid=document.getElementById('groupGrid'),groupMask=document.getElementById('groupMask');
 let saved={};(PLAN.floor_groups||[]).forEach((g,i)=>(g.floors||[]).forEach(k=>saved[k]='S'+i));
 let opts=['B','ONE','UP','G1','G2','G3','G4'];
 groupGrid.innerHTML=floors.map(f=>'<div class="floor-pick"><b>'+esc(f.label)+'</b><select data-floor="'+f.key+'">'+opts.map(o=>'<option value="'+o+'">'+({B:'지하층 공통',ONE:'1층 별도',UP:'지상 일반층',G1:'사용자 그룹 1',G2:'사용자 그룹 2',G3:'사용자 그룹 3',G4:'사용자 그룹 4'}[o])+'</option>')+'<option value="I_'+f.key+'">이 층만 별도</option></select></div>').join('');
 if(PLAN.floor_groups&&PLAN.floor_groups.length){document.querySelectorAll('.floor-pick select').forEach(s=>{let gi=(PLAN.floor_groups||[]).findIndex(g=>(g.floors||[]).includes(s.dataset.floor));s.value=gi>=0?(gi<4?'G'+(gi+1):'I_'+s.dataset.floor):'I_'+s.dataset.floor})}else setRecommendedGroups();
 groupMask.classList.add('show');
}
function confirmFloorGroups(){
 const groupMask=document.getElementById('groupMask');
 let map={};document.querySelectorAll('.floor-pick select').forEach(s=>{(map[s.value]||(map[s.value]=[])).push(floors.find(f=>f.key===s.dataset.floor))});
 activeGroups=Object.values(map).filter(Boolean).map(fs=>({name:groupLabel(fs),floors:fs}));
 PLAN.floor_groups=activeGroups.map(g=>{let r=PLAN.floors[g.floors[0].key]||{};return{name:g.name,floors:g.floors.map(f=>f.key),plan:{use:r.use||'',occupants:Number(r.occupants||0),vulnerable:r.vulnerable||'',primary_route:r.primary_route||'',alternate_route:r.alternate_route||'',guide:r.guide||'',checker:r.checker||''}}});
 const original=steps.slice(),head=original.slice(0,3),tail=original.slice(-3),grouped=[];
 activeGroups.forEach(g=>{['use','occupants','vulnerable','routes','staff'].forEach(k=>{let base=original.find(s=>s.floor&&s.floor.key===g.floors[0].key&&s.key===k);if(base){let copy={...base,floorGroup:g,floor:g.floors[0]};copy.q=base.q.replace(g.floors[0].label,g.name);grouped.push(copy)}})});
 steps.splice(0,steps.length,...head,...grouped,...tail);groupMask.classList.remove('show');save(()=>ask());
}
function msg(t,c){let d=document.createElement('div');d.className='msg '+c;d.textContent=t;chat.appendChild(d);down()}function bot(t){msg(t,'bot')}function me(t){msg(t,'me')}function down(){setTimeout(()=>scrollTo({top:document.body.scrollHeight,behavior:'smooth'}),40)}
function groupPlan(s){if(!s.floorGroup)return null;let keys=s.floorGroup.floors.map(f=>f.key),g=(PLAN.floor_groups||[]).find(x=>(x.floors||[]).some(k=>keys.includes(k)));if(g&&!g.plan)g.plan={};return g?g.plan:null}
function value(s){if(!s.floor)return PLAN[s.key]||s.def||'';let r=groupPlan(s)||PLAN.floors[(s.floorGroup?s.floorGroup.floors[0]:s.floor).key];if(s.key==='routes')return[r.primary_route||'',r.alternate_route||''];if(s.key==='staff')return[r.guide||'',r.checker||''];return r[s.key]??''}
function storeAnswer(s,v){let targets=s.floorGroup?s.floorGroup.floors:(s.floor?[s.floor]:[]);if(targets.length){let apply=r=>{if(s.key==='routes'){r.primary_route=v[0];r.alternate_route=v[1]}else if(s.key==='staff'){r.guide=v[0];r.checker=v[1]}else r[s.key]=s.type==='number'?Math.max(0,parseInt(v[0])||0):v[0]};targets.forEach(f=>apply(PLAN.floors[f.key]));let gp=groupPlan(s);if(gp)apply(gp)}else PLAN[s.key]=v[0]}
function prog(){let n=steps.length;bar.style.width=Math.round(step/n*100)+'%';pt.textContent=step>=n?'계획 작성 완료':'피난계획 작성 중';pc.textContent=Math.min(step,n)+' / '+n}
function save(done){state.textContent='저장 중…';let fd=new FormData();fd.append('act','save');fd.append('csrf',CSRF);fd.append('data',JSON.stringify(PLAN));fetch(location.href,{method:'POST',body:fd,credentials:'same-origin'}).then(async r=>{let t=await r.text(),j;try{j=JSON.parse(t)}catch(e){throw Error('저장 응답이 올바르지 않습니다. ('+r.status+')')}if(!r.ok||!j.ok)throw Error(j.error||'저장하지 못했습니다.');return j}).then(j=>{PLAN.updated=j.updated||PLAN.updated;state.textContent='저장됨 · '+(j.floor_count||0)+'개 층';if(typeof done==='function')done()}).catch(e=>{state.textContent='저장 실패';alert('피난계획 저장 실패\n'+e.message)})}
function saveAndView(){let f=document.createElement('form');f.method='post';f.action=location.href;f.target='_top';[['act','final_save'],['csrf',CSRF],['data',JSON.stringify(PLAN)],['return_url',RETURN_URL]].forEach(([n,v])=>{let i=document.createElement('input');i.type='hidden';i.name=n;i.value=v;f.appendChild(i)});document.body.appendChild(f);state.textContent='최종 저장 중…';f.submit()}
function ask(){prog();if(step>=steps.length)return finish();let s=steps[step];bot(s.q);let box=document.createElement('section');box.className='answer';let ins=[];
 if(s.type==='pair'){let vals=value(s),g=document.createElement('div');g.className='grid';s.labels.forEach((x,i)=>{let w=document.createElement('div'),l=document.createElement('label'),inp=document.createElement('input');l.textContent=x;inp.value=vals[i]||'';inp.placeholder=s.ph[i];w.append(l);if(s.pairOptions)w.appendChild(options(s.pairOptions[i],inp));w.append(inp);g.appendChild(w);ins.push(inp)});box.appendChild(g)}else{let l=document.createElement('label'),inp=document.createElement('input');l.textContent=s.type==='number'?'최대 인원':'답변';if(s.type==='number'){inp.type='number';inp.min=0;inp.max=99999}inp.value=value(s);inp.placeholder=s.ph||'';box.append(l);if(s.options)box.appendChild(options(s.options,inp));box.append(inp);ins=[inp]}
 if(s.hint){let h=document.createElement('div');h.className='hint';h.textContent=s.hint;box.appendChild(h)}let ac=document.createElement('div');ac.className='actions';if(step>0){let b=document.createElement('button');b.className='btn';b.textContent='이전 답변 수정';b.onclick=()=>{box.remove();step--;ask()};ac.appendChild(b)}let go=document.createElement('button');go.className='btn primary';go.textContent='저장하고 다음';go.onclick=()=>{let v=ins.map(i=>i.value.trim());if(v.some(x=>x===''))return ins.find(i=>!i.value.trim()).focus();storeAnswer(s,v);box.remove();me((s.floorGroup?s.floorGroup.name+' · ':'')+v.join(' · '));save(()=>{step++;ask()})};ac.appendChild(go);box.appendChild(ac);chat.appendChild(box);ins[0].focus();down()}
function options(items,inp){let w=document.createElement('div');w.className='options';items.forEach(v=>{let b=document.createElement('button');b.type='button';b.className='option';b.textContent=v;b.onclick=()=>{if(v==='직접 입력'){inp.value='';inp.focus()}else{inp.value=v;[...w.children].forEach(x=>x.classList.remove('on'));b.classList.add('on')}};w.appendChild(b)});return w}
function esc(v){let d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML}
function startReview(){chat.innerHTML='';step=0;bot('저장된 내용을 수정합니다. 먼저 같은 피난방법을 사용할 층 구성을 확인해주세요.');openFloorGrouping()}
function finish(saved=false){bot(saved?'저장된 피난 대피계획입니다. 내용을 확인하거나 수정할 수 있습니다.':'답변을 바탕으로 건물 전체 피난 대피계획을 정리했습니다. 아래 요약을 현장 상황과 비교해 최종 확인해주세요.');let total=floors.reduce((n,f)=>n+Number(PLAN.floors[f.key].occupants||0),0),d=document.createElement('section');d.className='summary';let x='<h2>피난 대피계획 최종 요약</h2>'+(PLAN.updated?'<p class="hint">마지막 저장 '+esc(PLAN.updated)+'</p>':'')+'<div class="overview"><p><b>대상:</b> '+esc(BUILDING.name||'건물')+' · 지상 '+FA+'층 / 지하 '+FB+'층 · 최대 '+total+'명</p><p><b>상황 전파:</b> '+esc(PLAN.alarm_method)+'</p><p><b>119 신고:</b> '+esc(PLAN.reporter)+' / <b>피난 지휘:</b> '+esc(PLAN.controller)+'</p><p><b>최종 집결지:</b> '+esc(PLAN.assembly_confirmed)+'</p><p><b>인원 확인:</b> '+esc(PLAN.headcount_method)+'</p></div>';let showGroups=activeGroups.length?activeGroups:floors.map(f=>({name:f.label,floors:[f]}));showGroups.forEach(g=>{let r=PLAN.floors[g.floors[0].key];x+='<div class="floor"><b>'+esc(g.name)+' · '+esc(r.use)+' · 층별 최대 '+Number(r.occupants||0)+'명</b><p>적용층: '+esc(g.floors.map(f=>f.label).join(', '))+'</p><p>피난약자: '+esc(r.vulnerable)+'</p><p>주 경로: '+esc(r.primary_route)+'</p><p>대체 경로: '+esc(r.alternate_route)+'</p><p>피난유도: '+esc(r.guide)+' / 잔류자 확인: '+esc(r.checker)+'</p></div>'});x+='<div class="overview"><p><b>특별 주의사항:</b> '+esc(PLAN.special_notes)+'</p><p>※ 실제 계단·비상구 개방 여부와 이동 가능 상태를 현장에서 확인한 뒤 사용하세요.</p></div><div class="actions"><button class="btn" onclick="startReview()">저장 내용 수정</button><button class="btn primary" onclick="saveAndView()">저장하고 피난계획 보기</button></div>';d.innerHTML=x;chat.appendChild(d);prog();down()}
if(FA+FB===0){bot('건물 층수 정보가 없습니다. 먼저 건물 기본정보에서 층수를 설정해주세요.');let a=document.createElement('a');a.className='btn primary';a.href='/building_setup_chat.php';a.textContent='건물 기본정보 설정';chat.appendChild(a)}else if(PLAN.updated&&Object.values(PLAN.floors||{}).some(r=>r&&(r.primary_route||r.use||r.guide))){restoreGroups();step=steps.length;finish(true)}else{bot((BUILDING.name||'이 건물')+'은 지상 '+FA+'층, 지하 '+FB+'층의 '+(BUILDING.use||'건물')+'로 확인됩니다.\n\n먼저 같은 피난방법을 사용할 층을 묶어주세요. 묶인 층은 한 번만 답하면 모두 적용됩니다.');openFloorGrouping()}
</script></body></html>
